#!/usr/bin/env python3
"""Create one real pinned audit source and run that independent host auditor once.

This caller neither invokes the old close/main nor owns a phone/native process.
The controller owns this Python process and must retain its complete termination
and output. Existing source/output namespaces reject; there is no retry branch.
"""
import base64
import hashlib
import json
import os
from pathlib import Path
import runpy
import stat
import sys
import time
import traceback

sys.dont_write_bytecode = True
ROOT = Path('/home/alex/codex-hepta-external902-independent-closure-audit-source-1ad3-01')
DRIVER = ROOT / 'audit_existing_closure.py'
AUDIT = Path('/home/alex/codex-hepta-external902-independent-closure-audit-1ad3-01')
DRIVER_PIN = {'bytes': 26038, 'sha256': '8e6bab425940cae081f0684e61b20b6dbf5f9568c20ddecc3e1ee8f907536d29'}
DRIVER_B64 = ''
CLOSURE_PIN = {'bytes': 55124, 'sha256': 'ffe4cc50c4a89d20cc7ccc284fa781604a31be2a8107a5fabdc3c50f87305719'}
PLAN_PIN = {'bytes': 2601, 'sha256': '77e77c83002b355692a1ca184992668409dc27136e58936520ccf55f419dc2a4'}
META = ('st_dev', 'st_ino', 'st_mode', 'st_uid', 'st_gid', 'st_nlink',
        'st_size', 'st_mtime_ns', 'st_ctime_ns')


def need(ok, why):
    if not ok:
        raise ValueError(why)


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def pin(raw):
    return {'bytes': len(raw), 'sha256': sha(raw)}


def enc(value):
    return (json.dumps(value, sort_keys=True, ensure_ascii=False,
        separators=(',', ':'), allow_nan=False) + '\n').encode()


def strict(raw):
    def pairs(items):
        out = {}
        for key, value in items:
            need(key not in out, 'duplicate JSON key')
            out[key] = value
        return out
    return json.loads(raw, object_pairs_hook=pairs,
        parse_constant=lambda _: (_ for _ in ()).throw(ValueError('nonfinite JSON')))


def meta(value):
    return [getattr(value, name) for name in META]


def parent_fd(path):
    path = Path(path)
    need(path.is_absolute() and '..' not in path.parts and 2 <= len(path.parts) <= 64,
        'fixed canonical path required')
    fd = os.open('/', os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC)
    try:
        for name in path.parts[1:-1]:
            new = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC,
                dir_fd=fd)
            os.close(fd)
            fd = new
        return fd, path.name
    except BaseException:
        os.close(fd)
        raise


def directory(path):
    parent, name = parent_fd(path)
    fd = None
    try:
        before = os.stat(name, dir_fd=parent, follow_symlinks=False)
        need(stat.S_ISDIR(before.st_mode), 'canonical directory required')
        fd = os.open(name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW | os.O_CLOEXEC,
            dir_fd=parent)
        need(meta(os.fstat(fd)) == meta(before)
            == meta(os.stat(name, dir_fd=parent, follow_symlinks=False)), 'directory changed on open')
        return fd, meta(before)
    except BaseException:
        if fd is not None:
            os.close(fd)
        raise
    finally:
        os.close(parent)


def read_original(path, expected_pin=None, expected_meta=None, maximum=1048576):
    path = Path(path)
    parent, name = parent_fd(path)
    fd = None
    try:
        pmeta = meta(os.fstat(parent))
        before = os.stat(name, dir_fd=parent, follow_symlinks=False)
        need(stat.S_ISREG(before.st_mode) and before.st_nlink == 1
            and 0 <= before.st_size <= maximum, 'bounded regular original required')
        if expected_meta is not None:
            need(meta(before) == expected_meta, 'original full9 changed')
        fd = os.open(name, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC,
            dir_fd=parent)
        need(meta(os.fstat(fd)) == meta(before), 'original changed before read')
        with os.fdopen(fd, 'rb', closefd=False) as stream:
            raw = stream.read(maximum + 1)
        need(len(raw) == before.st_size and meta(os.fstat(fd)) == meta(before)
            == meta(os.stat(name, dir_fd=parent, follow_symlinks=False)), 'original changed during read')
        need(meta(os.fstat(parent)) == pmeta, 'original parent changed during read')
    finally:
        if fd is not None:
            os.close(fd)
        os.close(parent)
    canonical, leaf = parent_fd(path)
    try:
        need(leaf == name and meta(os.fstat(canonical)) == pmeta
            and meta(os.stat(leaf, dir_fd=canonical, follow_symlinks=False)) == meta(before),
            'original canonical path changed')
    finally:
        os.close(canonical)
    if expected_pin is not None:
        need(pin(raw) == expected_pin, 'exact original source/result bytes differ')
    return raw, {'path': str(path), **pin(raw), 'metadata': meta(before)}


def put(fd, name, raw):
    need('/' not in name and name not in ('', '.', '..'), 'fixed new leaf required')
    item = os.open(name, os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW | os.O_CLOEXEC,
        0o600, dir_fd=fd)
    with os.fdopen(item, 'wb') as stream:
        stream.write(raw)
        stream.flush()
        os.fsync(stream.fileno())
    os.fsync(fd)
    body, row = read_original(ROOT / name, pin(raw), maximum=1048576)
    need(body == raw and row['metadata'][3] == os.geteuid()
        and stat.S_IMODE(row['metadata'][2]) == 0o600, 'new source/receipt readback differs')
    return row


def root_bookend(identity, names):
    fd, current = directory(ROOT)
    try:
        need(current[:2] == identity[:2] and current[2:6] == identity[2:6]
            and sorted(os.listdir(fd)) == sorted(names), 'new source namespace changed')
    finally:
        os.close(fd)
    return current


def main():
    started = time.monotonic()
    parent = root_fd = None
    created = entered = returned = False
    exit_code = None
    phase = 'fixed_payload'
    identity = None
    retained = {}
    try:
        need(type(CALLER_SOURCE) is bytes and len(CALLER_SOURCE) <= 131072,
            'exact retained caller bytes required')
        driver = base64.b64decode(DRIVER_B64, validate=True)
        need(pin(driver) == DRIVER_PIN, 'fixed audit driver payload differs')
        need(ROOT.parent == AUDIT.parent == Path('/home/alex')
            and DRIVER == ROOT / 'audit_existing_closure.py', 'fixed source/output namespace differs')
        phase = 'create_new_real_source'
        parent, name = parent_fd(ROOT)
        need(not os.path.lexists(ROOT) and not os.path.lexists(AUDIT),
            'new source and audit outputs must both be absent; no retry or new suffix')
        os.mkdir(name, mode=0o700, dir_fd=parent)
        created = True
        os.fsync(parent)
        root_fd, identity = directory(ROOT)
        need(identity[3] == os.geteuid() and stat.S_IMODE(identity[2]) == 0o700,
            'owned private source namespace required')
        retained['intent'] = put(root_fd, 'STAGE-INTENT.json', enc({
            'schema': 'hepta.existing-failed-closure.independent-host-caller-intent.v1',
            'caller': pin(CALLER_SOURCE), 'driver': {'path': str(DRIVER), **DRIVER_PIN},
            'equivalent_standalone_cli': ['/usr/bin/python3', '-I', '-B', str(DRIVER), '--execute-independent-host-audit-once'],
            'driver_sys_argv': [str(DRIVER), '--execute-independent-host-audit-once'],
            'in_process_runpy_entry': True, 'new_output': str(AUDIT),
            'additional_child_processes': 0, 'controller_owns_this_python_process': True,
            'automatic_retry': False, 'original_close_main_calls': 0,
            'phone_calls': 0, 'native_dispatches': 0, 'new_native_closure': False,
            'boundary_publications': 0, 'case_pass': False}))
        retained['caller'] = put(root_fd, 'CALLER.original.py', CALLER_SOURCE)
        retained['driver'] = put(root_fd, DRIVER.name, driver)
        retained['stage_result'] = put(root_fd, 'STAGE-RESULT.json', enc({
            'schema': 'hepta.existing-failed-closure.independent-host-source-stage.v1',
            'state': 'REAL_PINNED_HOST_AUDIT_SOURCE_CREATED_ONLY',
            'sources': {key: retained[key] for key in ('caller', 'driver')},
            'intent': retained['intent'], 'stage_root': str(ROOT),
            'driver_entered': False, 'phone_calls': 0, 'case_pass': False}))
        names = ['STAGE-INTENT.json', 'CALLER.original.py', DRIVER.name, 'STAGE-RESULT.json']
        source_directory_before_entry = root_bookend(identity, names)
        os.close(root_fd)
        root_fd = None
        os.close(parent)
        parent = None
        read_original(DRIVER, DRIVER_PIN, retained['driver']['metadata'])
        phase = 'one_independent_host_driver'
        argv = sys.argv[:]
        try:
            sys.argv = [str(DRIVER), '--execute-independent-host-audit-once']
            entered = True
            try:
                runpy.run_path(str(DRIVER), run_name='__main__')
            except SystemExit as error:
                returned = True
                exit_code = error.code
                need(type(exit_code) is int and exit_code == 0,
                    'independent audit did not return SystemExit(0)')
            else:
                raise ValueError('independent audit returned without its pinned main exit')
        finally:
            sys.argv = argv
        phase = 'actual_derived_result_bookend'
        need(root_bookend(identity, names) == source_directory_before_entry,
            'source directory full9 changed while independent driver ran')
        read_original(DRIVER, DRIVER_PIN, retained['driver']['metadata'])
        read_original(ROOT / 'CALLER.original.py', pin(CALLER_SOURCE), retained['caller']['metadata'])
        equality_raw, equality_row = read_original(AUDIT / 'BYTE-EQUALITY.json')
        equality = strict(equality_raw)
        need(equality.get('schema') == 'hepta.existing-failed-closure.independent-host-byte-equality.v1'
            and equality.get('state') == 'EXISTING_FAILED_CLOSURE_FULL_OBJECT_RECOMPUTED_BYTE_EQUAL'
            and equality.get('driver') == {'path': str(DRIVER), **DRIVER_PIN}
            and {key: equality['original_closure'][key] for key in ('bytes', 'sha256')} == CLOSURE_PIN
            and {key: equality['original_plan'][key] for key in ('bytes', 'sha256')} == PLAN_PIN,
            'independent audit receipt identity differs')
        need(equality.get('historical_original_host_inputs_exact') is True
            and equality.get('owned_read_fd_bookend_complete') is True
            and equality.get('old_mac_sender_capture_unknown_preserved') is True,
            'complete original host inputs/FD/history proof differs')
        for key in ('original_main_calls', 'original_close_calls', 'phone_calls',
                    'native_dispatches', 'sender_runs', 'snapshot_calls', 'boundary_publications', 'signals'):
            need(type(equality.get(key)) is int and equality[key] == 0, 'unexpected audit action: ' + key)
        for key in ('new_native_closure', 'eligible_for_publication', 'fresh_phone_clearance',
                    'component_qualified', 'case_pass', 'automatic_retry',
                    'source_modules_replaced_or_relabelled', 'original_host_metadata_replaced',
                    'complete_object_fields_deleted_or_normalized'):
            need(equality.get(key) is False, 'unexpected audit scope: ' + key)
        _, recomputed = read_original(AUDIT / 'RECOMPUTED-EXPECTED-CLOSURE.json', CLOSURE_PIN)
        need(equality['recomputed'] == {key: recomputed[key] for key in ('path', 'bytes', 'sha256')},
            'recomputed closure descriptor differs')
        read_original(AUDIT / 'BYTE-EQUALITY.json', pin(equality_raw), equality_row['metadata'])
        root_fd, current = directory(ROOT)
        need(current[:2] == identity[:2], 'source directory replaced before receipt')
        result = {'schema': 'hepta.existing-failed-closure.independent-host-caller-result.v1',
            'state': 'INDEPENDENT_HOST_AUDIT_RETURNED_ZERO_AND_BYTE_EQUALITY_RETAINED',
            'caller': retained['caller'], 'driver': retained['driver'],
            'source_stage': retained['stage_result'], 'audit_receipt': equality_row,
            'recomputed_closure': recomputed, 'driver_entered': entered, 'driver_returned': returned,
            'driver_exit_code': exit_code, 'in_process_runpy_entry': True,
            'controller_completion_and_full_stdout_stderr_still_required': True,
            'elapsed_seconds': time.monotonic() - started, 'original_main_calls': 0,
            'original_close_calls': 0, 'phone_calls': 0, 'native_dispatches': 0,
            'new_native_closure': False, 'boundary_publications': 0,
            'fresh_phone_clearance': False, 'case_pass': False, 'automatic_retry': False,
            'old_mac_sender_capture_unknown_preserved': True}
        result_row = put(root_fd, 'CALLER-RESULT.json', enc(result))
        root_bookend(identity, names + ['CALLER-RESULT.json'])
        print(enc({'state': result['state'], 'result': result_row,
            'audit_receipt': equality_row, 'driver_exit_code': 0,
            'phone_calls': 0, 'case_pass': False}).decode(), end='')
        return 0
    except BaseException as error:
        failure = {'schema': 'hepta.existing-failed-closure.independent-host-caller-failure.v1',
            'state': 'HOST_AUDIT_CALLER_FAILED_OR_UNKNOWN_NO_RETRY',
            'phase': phase, 'error_type': type(error).__name__, 'detail': str(error)[:2000],
            'new_source_created': created, 'driver_entered': entered,
            'driver_returned': returned, 'driver_exit_code': exit_code,
            'new_output': str(AUDIT), 'source_stage': str(ROOT),
            'phone_calls': 0, 'case_pass': False, 'automatic_retry': False,
            'new_native_closure': False, 'fresh_phone_clearance': False,
            'old_mac_sender_capture_unknown_preserved': True}
        if created:
            try:
                if root_fd is None:
                    root_fd, current = directory(ROOT)
                    need(identity is not None and current[:2] == identity[:2],
                        'source directory identity unknown during failure retention')
                failure['retained'] = put(root_fd, 'CALLER-FAILURE.json', enc(failure))
            except BaseException as retention_error:
                failure['retention_error'] = {'type': type(retention_error).__name__,
                    'detail': str(retention_error)[:1000]}
        traceback.print_exc(file=sys.stderr)
        print(enc(failure).decode(), end='')
        return 1
    finally:
        if root_fd is not None:
            os.close(root_fd)
        if parent is not None:
            os.close(parent)


if __name__ == '__main__':
    raise SystemExit(main())
